import boto3
import os

def get_cloudwatch_logs_client():
    region_name = os.environ.get('AWS_REGION', 'us-east-1')
    return boto3.client('logs', region_name=region_name)

import os
import time
import json
from datetime import datetime, timedelta
from typing import Dict, Any
from observability_client import get_cloudwatch_logs_client

def fetch_recent_logs(log_group_names: list[str], minutes_ago: int = 60, filters: Dict[str, Any] = None):
    client = get_cloudwatch_logs_client()

    end_time = int(time.time())
    start_time = int(end_time - (minutes_ago * 60))

    query_parts = ["fields @timestamp, @message"]
    if filters:
        for key, value in filters.items():
            # Assuming structured log messages are JSON strings in the 'message' field
            # And we are filtering on top-level keys within that JSON
            query_parts.append(f"filter json_parse(@message).{key} = '{value}'")

    query_parts.append("sort @timestamp desc")
    query = " | ".join(query_parts)

    start_query_response = client.start_query(
        logGroupNames=log_group_names,
        startTime=start_time,
        endTime=end_time,
        queryString=query,
        limit=100
    )

    query_id = start_query_response['queryId']

    response = None
    while response is None or response['status'] == 'Running':
        time.sleep(1)  # Wait for the query to complete
        response = client.get_query_results(
            queryId=query_id
        )

    # Parse results
    recent_logs = []
    for result_set in response['results']:
        log_entry = {}
        for field in result_set:
            if field['field'] == '@message':
                try:
                    log_entry['message'] = json.loads(field['value'])
                except json.JSONDecodeError:
                    log_entry['message'] = field['value'] # If not JSON, keep as string
            else:
                log_entry[field['field'].replace('@', '')] = field['value']
        recent_logs.append(log_entry)

    return recent_logs

if __name__ == '__main__':
    LOG_GROUP = os.environ.get('LOG_GROUP_NAME', 'my-application-logs')

    print(f"Fetching recent logs for log group: {LOG_GROUP} with a filter...")
    # Example: Fetch logs where service is 'user-service'
    filters = {"service": "user-service"}
    logs = fetch_recent_logs(log_group_names=[LOG_GROUP], minutes_ago=60, filters=filters)

    if logs:
        print(f"Found {len(logs)} recent logs:")
        for log_entry in logs:
            print(json.dumps(log_entry, indent=2))
    else:
        print("No recent logs found with the specified filters.")

    print(f"\nFetching all recent logs for log group: {LOG_GROUP} (no filters)...")
    all_logs = fetch_recent_logs(log_group_names=[LOG_GROUP], minutes_ago=60)
    if all_logs:
        print(f"Found {len(all_logs)} recent logs:")
        # print first 5 for brevity
        for log_entry in all_logs[:5]: 
            print(json.dumps(log_entry, indent=2))
    else:
        print("No recent logs found.")

import os
from typing import List, Dict, Any
from google.cloud import aiplatform

def summarize_error_logs(project_id: str, location: str, error_logs: List[Dict[str, Any]]) -> str:
    aiplatform.init(project=project_id, location=location)

    # Use a generative model (e.g., Gemini or text-bison)
    # For this example, we'll use a placeholder model name. 
    # In a real scenario, you'd specify a concrete model like 'gemini-pro' or 'text-bison@001'
    model = aiplatform.preview.language_models.TextGenerationModel.from_pretrained("gemini-pro")

    if not error_logs:
        return "No error logs provided for summarization."

    log_messages = [log.get('message', {}).get('event', str(log)) for log in error_logs]
    combined_logs_text = "\n".join([str(msg) for msg in log_messages])

    prompt = f"Summarize the following error log findings for an incident review. Focus on identifying patterns, root causes, and impact:\n\n{combined_logs_text}\n\nSummary:"

    response = model.predict(
        prompt,
        max_output_tokens=1024,  # Adjust as needed
        temperature=0.2,       # Adjust for creativity vs. factualness
    )

    return response.text

if __name__ == '__main__':
    PROJECT_ID = os.environ.get('GOOGLE_CLOUD_PROJECT')  # e.g., your-gcp-project-id
    LOCATION = os.environ.get('GOOGLE_CLOUD_REGION', 'us-central1') # e.g., us-central1

    if not PROJECT_ID:
        print("Please set the GOOGLE_CLOUD_PROJECT environment variable.")
    else:
        # Example error logs (in a real scenario, these would come from query_error_logs.py)
        example_error_logs = [
            {
                "timestamp": "2026-09-19T10:00:00Z",
                "message": {"level": "ERROR", "service": "user-service", "event": "Failed to connect to database", "details": {"db_host": "db-prod-1"}}
            },
            {
                "timestamp": "2026-09-19T10:01:00Z",
                "message": {"level": "ERROR", "service": "user-service", "event": "Database connection timed out", "details": {"db_host": "db-prod-1"}}
            },
            {
                "timestamp": "2026-09-19T10:05:00Z",
                "message": {"level": "ERROR", "service": "payment-service", "event": "Third-party payment gateway error", "details": {"gateway": "stripe"}}
            },
        ]

        summary = summarize_error_logs(PROJECT_ID, LOCATION, example_error_logs)
        print("\nIncident Summary:")
        print(summary)
